let clipboardFiles = undefined;
async function getClipboardFiles() {
    try {
        if (!clipboardFiles) {
            clipboardFiles = require("../build/Release/clipboardFiles.node");
        }
        const promise = clipboardFiles.getClipboardFiles();
        return await promise;
    } catch (error) {
        console.error(error);
        return [];
    }
}

module.exports = {
    getClipboardFiles: getClipboardFiles
}
